<head>
<meta charset="utf-8">
<title>State of Developer Ecosystem 2024</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700;800&display=swap');

  :root {
    --bg-deep: #080c12;
    --bg-card: #111820;
    --bg-card-alt: #151d28;
    --border: #1c2736;
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --text-muted: #5c6570;
    --blue: #58a6ff;
    --blue-dim: #388bfd;
    --green: #3fb950;
    --amber: #d2991d;
    --orange: #f0883e;
    --purple: #a371f7;
    --teal: #39d353;
    --red: #f85149;
    --js-yellow: #f0db4f;
    --ts-blue: #3178c6;
    --python-blue: #306998;
    --python-yellow: #ffd43b;
    --rust-orange: #dea584;
    --go-cyan: #00add8;
    --postgres-blue: #336791;
    --mysql-orange: #f29111;
    --aws-orange: #ff9900;
    --azure-blue: #0078d4;
    --gcp-red: #ea4335;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: 'Inter', system-ui, -apple-system, sans-serif;
    background: var(--bg-deep);
    color: var(--text-primary);
    width: 1600px;
    min-height: 2262px;
    -webkit-font-smoothing: antialiased;
  }

  .poster {
    width: 1600px;
    min-height: 2262px;
    padding: 60px 70px;
    display: flex;
    flex-direction: column;
    gap: 40px;
    background: linear-gradient(180deg, #080c12 0%, #0a1018 30%, #0c1420 100%);
  }

  /* HEADER */
  .header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    padding-bottom: 32px;
    border-bottom: 1px solid var(--border);
  }
  .header-left h1 {
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 52px;
    font-weight: 800;
    letter-spacing: -1px;
    line-height: 1.1;
    color: #fff;
  }
  .header-left h1 span.accent { color: var(--blue); }
  .header-left .subtitle {
    font-family: 'JetBrains Mono', monospace;
    font-size: 22px;
    font-weight: 500;
    color: var(--text-secondary);
    margin-top: 8px;
    letter-spacing: 2px;
  }
  .header-right {
    text-align: right;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .stat-badge {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 14px 20px;
  }
  .stat-badge .stat-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 28px;
    font-weight: 700;
    color: var(--blue);
  }
  .stat-badge .stat-label {
    font-size: 14px;
    color: var(--text-secondary);
  }
  .source-line {
    font-size: 12px;
    color: var(--text-muted);
    font-weight: 400;
  }

  /* SECTION TITLES */
  .section-title {
    font-family: 'JetBrains Mono', monospace;
    font-size: 17px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 3px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .section-title::before {
    content: '';
    display: block;
    width: 24px;
    height: 2px;
    background: var(--blue);
  }

  /* LANGUAGE CHART - CENTERPIECE */
  .chart-section {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 36px 40px 28px 40px;
  }
  .chart-section .chart-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 20px;
  }
  .chart-section .chart-header h3 {
    font-family: 'JetBrains Mono', monospace;
    font-size: 20px;
    font-weight: 700;
    color: #fff;
  }
  .chart-section .chart-header p {
    font-size: 14px;
    color: var(--text-secondary);
    max-width: 500px;
    line-height: 1.5;
  }
  .highlight-ts {
    color: var(--blue);
    font-weight: 600;
  }
  .highlight-py {
    color: var(--green);
    font-weight: 600;
  }

  /* TWO-COLUMN LAYOUT */
  .two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }
  .card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 32px 36px;
  }

  /* THREE-COLUMN LAYOUT */
  .three-col {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 24px;
  }

  /* PROMISE INDEX */
  .promise-bar {
    margin-top: 16px;
  }
  .promise-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 10px;
  }
  .promise-rank {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    font-weight: 600;
    color: var(--text-muted);
    width: 20px;
    text-align: right;
  }
  .promise-name {
    font-size: 14px;
    font-weight: 500;
    width: 90px;
    text-align: right;
    color: var(--text-primary);
  }
  .promise-track {
    flex: 1;
    height: 26px;
    background: var(--bg-card-alt);
    border-radius: 4px;
    overflow: hidden;
    position: relative;
  }
  .promise-fill {
    height: 100%;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 8px;
  }
  .promise-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    font-weight: 700;
    color: #fff;
  }

  /* DATABASE CHART */
  .db-chart { margin-top: 28px; }
  .db-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 16px;
  }
  .db-label {
    font-size: 15px;
    font-weight: 500;
    width: 100px;
    text-align: right;
    color: var(--text-primary);
  }
  .db-bar-group { flex: 1; display: flex; flex-direction: column; gap: 3px; }
  .db-bar-track {
    height: 22px;
    background: var(--bg-card-alt);
    border-radius: 3px;
    overflow: hidden;
    position: relative;
  }
  .db-bar-fill {
    height: 100%;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 8px;
    transition: width 0.3s;
  }
  .db-bar-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
    color: #fff;
  }
  .db-years {
    display: flex;
    gap: 6px;
    font-size: 11px;
    color: var(--text-muted);
    font-family: 'JetBrains Mono', monospace;
  }
  .db-years span { width: 70px; text-align: center; }

  /* METRIC CARDS */
  .metric-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-top: 16px;
  }
  .metric-card {
    background: var(--bg-card-alt);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 18px 20px;
    text-align: center;
  }
  .metric-card .m-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 32px;
    font-weight: 800;
    line-height: 1.1;
  }
  .metric-card .m-label {
    font-size: 12px;
    color: var(--text-secondary);
    margin-top: 6px;
    line-height: 1.4;
  }

  /* AI SECTION */
  .ai-section {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 36px 40px;
  }
  .ai-big-stat {
    font-family: 'JetBrains Mono', monospace;
    font-size: 80px;
    font-weight: 900;
    line-height: 1;
    background: linear-gradient(135deg, var(--teal) 0%, var(--blue) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* SVG Chart */
  .lang-chart-svg { width: 100%; }

  /* ANNOTATION CALLOUT */
  .callout {
    background: var(--bg-card-alt);
    border-left: 3px solid var(--blue);
    border-radius: 0 8px 8px 0;
    padding: 14px 18px;
    font-size: 14px;
    color: var(--text-secondary);
    line-height: 1.5;
  }
  .callout strong { color: var(--blue); }

  /* FOOTER */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 20px;
    border-top: 1px solid var(--border);
    font-size: 12px;
    color: var(--text-muted);
    font-family: 'JetBrains Mono', monospace;
  }
</style>
