const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const posterPath = path.resolve('/app/output/poster.html');
  const outputPath = path.resolve('/app/output/final_poster.png');

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });

  await page.goto(`file://${posterPath}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(2000);

  // Get the full poster element dimensions
  const posterEl = await page.$('.poster');
  const bounds = await posterEl.boundingBox();

  // Set viewport to match poster content with some padding
  await page.setViewportSize({
    width: Math.ceil(bounds.width) + 20,
    height: Math.ceil(bounds.height + bounds.y) + 40
  });

  await page.waitForTimeout(500);

  await page.screenshot({
    path: outputPath,
    fullPage: true,
    clip: {
      x: 0,
      y: 0,
      width: Math.ceil(bounds.width),
      height: Math.ceil(bounds.height + bounds.y)
    }
  });

  console.log(`Poster rendered to: ${outputPath}`);
  console.log(`Dimensions: ${Math.ceil(bounds.width)}x${Math.ceil(bounds.height + bounds.y)}`);

  await browser.close();
})();

